import {appShellApp} from '@github-ui/app-shell'
import {dynamic} from '@github-ui/dynamic'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import {registerDataRouterApp} from '@github-ui/react-core/register-app'

import {reactSandboxFutureAppBuilder} from './config/app-builder'
import {reactSandboxFutureClientErrorRoute} from './routes/client-error-route'
import {reactSandboxFutureDashboardDiscussionsRoute} from './routes/dashboard-discussions-route'
import {reactSandboxFutureDashboardIssuesRoute} from './routes/dashboard-issues-route'
import {reactSandboxFutureDashboardPullsRoute} from './routes/dashboard-pulls-route'
import {reactSandboxFutureDashboardRoute} from './routes/dashboard-route'
import {reactSandboxFutureHashNavRoute} from './routes/hash-nav-route'
import {reactSandboxFutureIdRoute} from './routes/id-route'
import {reactSandboxFutureIndexRoute} from './routes/index-route'
import {reactSandboxFutureLayoutRoute} from './routes/layout-route'
import {reactSandboxFuturePreloadRoute} from './routes/preload-route'
import {reactSandboxFutureRailsPartialsRoute} from './routes/rails-partials-route'

const ReactSandboxFutureLayoutRoute = dynamic(async () => {
  const mod = await import('./routes/Layout')
  return {default: mod.ReactSandboxFutureLayout}
})

const ReactSandboxFutureIndex = dynamic(async () => {
  const mod = await import('./routes/Index')
  return {default: mod.ReactSandboxFutureIndex}
})

const ReactSandboxFutureId = dynamic(async () => {
  const mod = await import('./routes/Id')
  return {default: mod.ReactSandboxFutureId}
})

const ReactSandboxClientError = dynamic(async () => {
  const mod = await import('./components/ClientError')
  return {default: mod.ClientError}
})

const ReactSandboxHashNav = dynamic(async () => {
  const mod = await import('./routes/HashNav')
  return {default: mod.HashNav}
})

const ReactSandboxRailsPartial = dynamic(async () => {
  const mod = await import('./routes/RailsPartials')
  return {default: mod.RailsPartials}
})

const ReactSandboxPreload = dynamic(async () => {
  const mod = await import('./routes/Preload')
  return {default: mod.Preload}
})

const ReactSandboxFutureDashboard = dynamic(async () => {
  const mod = await import('./routes/Dashboard')
  return {default: mod.ReactSandboxFutureDashboard}
})

const ReactSandboxFutureDiscussions = dynamic(async () => {
  const mod = await import('./routes/Discussions')
  return {default: mod.Discussions}
})

const ReactSandboxFutureIssues = dynamic(async () => {
  const mod = await import('./routes/Issues')
  return {default: mod.Issues}
})

const ReactSandboxFuturePulls = dynamic(async () => {
  const mod = await import('./routes/Pulls')
  return {default: mod.Pulls}
})

export const reactSandboxFutureApp = reactSandboxFutureAppBuilder.createDataRouterAppFromRoutes(
  [
    reactSandboxFutureLayoutRoute.toRoute({
      Component: ReactSandboxFutureLayoutRoute,
      children: [
        reactSandboxFutureIndexRoute.toRoute({Component: ReactSandboxFutureIndex}),
        reactSandboxFutureIdRoute.toRoute({Component: ReactSandboxFutureId}),
        reactSandboxFutureClientErrorRoute.toRoute({Component: ReactSandboxClientError}),
        reactSandboxFutureHashNavRoute.toRoute({Component: ReactSandboxHashNav}),
        reactSandboxFutureRailsPartialsRoute.toRoute({Component: ReactSandboxRailsPartial}),
        reactSandboxFuturePreloadRoute.toRoute({Component: ReactSandboxPreload}),
        reactSandboxFutureDashboardRoute.toRoute({
          Component: ReactSandboxFutureDashboard,
          children: [
            reactSandboxFutureDashboardIssuesRoute.toRoute({Component: ReactSandboxFutureIssues}),
            reactSandboxFutureDashboardPullsRoute.toRoute({Component: ReactSandboxFuturePulls}),
            reactSandboxFutureDashboardDiscussionsRoute.toRoute({Component: ReactSandboxFutureDiscussions}),
          ],
        }),
      ],
    }),
  ],
  {tanStackRouterEnabled: () => isFeatureEnabled('react_sandbox_future_tanstack')},
)

registerDataRouterApp(reactSandboxFutureApp)
registerDataRouterApp(appShellApp)
